<?php
namespace App\Http\Controllers\SuperAdmin;
use App\Http\Controllers\Controller; use App\Models\Store; use Illuminate\Http\Request;
class ShopController extends Controller { public function index(Request $r){$q=Store::with('user')->withCount(['products','sellerOrders','violations','reports']);if($r->q)$q->where(fn($x)=>$x->where('name','like','%'.$r->q.'%')->orWhereHas('user',fn($u)=>$u->where('name','like','%'.$r->q.'%')->orWhere('email','like','%'.$r->q.'%')));if($r->status)$q->where('status',$r->status);$shops=$q->latest()->paginate(20)->withQueryString();return view('superadmin.shops.index',compact('shops'));} public function show(Store $shop){$shop->load(['user','products','sellerOrders','violations','reports','products.moderationScans'])->loadCount(['products','sellerOrders','violations','reports']);$stats=['active_products'=>$shop->products()->where('is_active',true)->count(),'suspended_products'=>$shop->products()->whereIn('moderation_status',['flagged','rejected'])->count(),'completed_orders'=>$shop->sellerOrders()->where('status','completed')->count(),'cancelled_orders'=>$shop->sellerOrders()->where('status','cancelled')->count(),'sales'=>$shop->sellerOrders()->where('status','completed')->sum('seller_total'),'reviews'=>\App\Models\Review::whereHas('product',fn($q)=>$q->where('store_id',$shop->id))->count()];return view('superadmin.shops.show',compact('shop','stats'));} }
